#!/usr/bin/env node
/**
 * ОТКАЗ СТАБИЛЬНОГО ВЫПУСКА: что сейчас в публичном реестре и что делать дальше.
 *
 * Красный шаг в GitHub Actions отвечает на вопрос «почему встали» — он виден в
 * логе. У выпускного потока дорогой вопрос ДРУГОЙ: **уехало ли что-нибудь**.
 * Лог на него не отвечает, а цена ошибки несимметрична: перезапуск после
 * «ничего не уехало» бесплатен, перезапуск после «уехала половина» жжёт номера
 * и разводит реестр с репозиторием. Поэтому отказ здесь называет состояние
 * реестра, а не только причину падения (`tasker:BASER2-192`).
 *
 * ПОЧЕМУ ЭТО КОД, А НЕ ТЕКСТ В YAML. Воркфлоу пробами не покрывается — его
 * исполняет чужой движок. Покрыто то, что воркфлоу ЗОВЁТ, и суждение «что
 * сейчас в реестре» — ровно тот случай: ошибиться в нём легко (скопировать
 * успокоительное «не уехало ничего» в отказ, случившийся после публикации), а
 * заметить ошибку можно только на живом выпуске, то есть уже дорого.
 *
 * РУБЕЖ БЕРЁТСЯ ИЗ СОСТОЯНИЯ ШАГОВ ПОТОКА, а не из отметок, которые поток
 * ставит себе сам: движок и так знает, дошёл ли прогон до публикации и чем та
 * кончилась (`steps.<id>.outcome`). Своя бухгалтерия рубежей была бы вторым
 * источником правды о том же — и разошлась бы с первым молча.
 *
 * ШАГОВ ДЛЯ ЭТОГО ДВА, И ВТОРОЙ ПОЯВИЛСЯ НЕ ДЛЯ КРАСОТЫ (`tasker:BASER2-263`).
 * После публикации у потока осталось ещё две работы: донести коммит версий и
 * теги до `main` и ПРИНЯТЬ выпуск установкой из публичного реестра. Отказ на
 * каждой из них означает разное — «реестр ушёл вперёд репозитория» и «уехало
 * всё, репозиторий в курсе, но у потребителя оно не работает», — и лечится
 * тоже разным. Различить их по одному лишь состоянию публикации нельзя, потому
 * что оно у обоих `success`.
 *
 * ЧТО ЗДЕСЬ ЗНАЮТ ПРО NPM (сверено 2026-08-06, политика unpublish npmjs.com):
 * снять выпущенное можно 72 часа и только если от пакета никто не зависит, а
 * номер после этого НЕ переиспользуется — «Once `package@version` has been
 * used, you can never use it again». Значит уехавший номер занят навсегда, и
 * отказ обязан говорить об этом до того, как человек нажмёт «перезапустить».
 *
 * ЧЕГО ЗДЕСЬ НЕТ. Скрипт не ходит в реестр и ничего не чинит: он зовётся на
 * упавшем прогоне, где право на публикацию ещё живо, а состояние уже неясно —
 * действовать в таком месте автоматом опаснее, чем назвать факты человеку.
 * Сверку с реестром он поэтому НАЗЫВАЕТ командой, а не выполняет.
 *
 * ```
 * node .github/scripts/release-refusal.mjs <outcome публикации> <outcome записи в main>
 * ```
 *
 * stdout — markdown для `$GITHUB_STEP_SUMMARY`. Выход `0` — рубеж опознан,
 * `2` — не опознан (отказ печатается и тогда, но осторожный).
 */

import { pathToFileURL } from 'node:url';

/**
 * Рубежи выпуска — по тому, что необратимо к этому моменту.
 *
 * `readiness`  — до публикации: в реестр не уехало ничего.
 * `publishing` — внутри публикации: пакеты уезжают по одному, часть могла уехать.
 * `published`  — публикация прошла, а запись в `main` — нет: реестр ушёл вперёд репозитория.
 * `delivered`  — уехало всё и репозиторий в курсе; упало то, что идёт дальше, — приёмка.
 * `unknown`    — рубеж не опознан; единственный честный ответ — «проверь реестр».
 */
export const STAGES = [
  'readiness',
  'publishing',
  'published',
  'delivered',
  'unknown',
];

/** Команда сверки — одна на все отказы, где реестр надо спросить. */
const ASK_REGISTRY = 'npm view <имя>@<номер> version';

/**
 * Рубеж по тому, чем кончились шаг публикации и шаг записи в `main`.
 *
 * Словарь — движка: `success` · `failure` · `cancelled` · `skipped` · пусто
 * (шаг не запускался вовсе). Отмена приравнена к падению НАМЕРЕННО: прогон,
 * снятый посреди публикации, оставляет ровно ту же неопределённость, а разница
 * «сняли или упало» на состояние реестра не влияет.
 *
 * Второй аргумент спрашивается ТОЛЬКО после успешной публикации: до неё он
 * ничего не различает — в реестр не уехало ничего независимо от того, что там
 * с записью в репозиторий.
 *
 * @param {string} publish значение `steps.<id>.outcome` шага публикации
 * @param {string} [push] то же у шага записи коммита версий и тегов в `main`
 * @returns {typeof STAGES[number]}
 */
export function stageOf(publish, push = '') {
  switch (publish) {
    case '':
    case 'skipped':
      return 'readiness';
    case 'failure':
    case 'cancelled':
      return 'publishing';
    case 'success':
      break;
    default:
      return 'unknown';
  }

  switch (push) {
    // Запись в `main` не дошла — репозиторий не знает про уехавшее.
    case '':
    case 'skipped':
    case 'failure':
    case 'cancelled':
      return 'published';
    // Уехало всё, репозиторий в курсе: упало то, что идёт после, — приёмка.
    case 'success':
      return 'delivered';
    default:
      return 'unknown';
  }
}

/**
 * @typedef {object} Refusal
 * @property {typeof STAGES[number]} stage
 * @property {'untouched'|'possibly-partial'|'complete'|'unknown'} registry что уехало в npm
 * @property {boolean} reversible можно ли перезапустить выпуск с нуля без последствий
 * @property {string} headline заголовок отказа
 * @property {string[]} state что сейчас известно про реестр и репозиторий
 * @property {string[]} next что делать человеку
 */

/**
 * Суждение об отказе: состояние мира и следующий шаг.
 *
 * @param {typeof STAGES[number]} stage
 * @returns {Refusal}
 */
export function refusal(stage) {
  switch (stage) {
    case 'readiness':
      return {
        stage,
        registry: 'untouched',
        reversible: true,
        headline:
          'Выпуск отказан на готовности — в публичный реестр не уехало ничего',
        state: [
          'Публикация не начиналась: `nx release` этим прогоном не запускался.',
          'Реестр не тронут, теги выпуска не поставлены, `main` не двигался.',
          'Номера в манифестах остались теми же — ни один не сгорел.',
        ],
        next: [
          'Чини в PR, а не в прогоне выпуска: готовность здесь — та же `pnpm verify`, что у вахтёра на выходе и у приёмки, значит красное здесь краснеет и на твоей машине.',
          'После влития запусти выпуск заново — с нуля и без оглядки на этот прогон.',
        ],
      };

    case 'publishing':
      return {
        stage,
        registry: 'possibly-partial',
        reversible: false,
        headline:
          'Выпуск отказан ВНУТРИ публикации — часть пакетов могла уже уехать',
        state: [
          '`nx release` публикует пакеты по одному и упавший прогон уехавшее НЕ откатывает.',
          'Номер, попавший в npm, занят навсегда: снять выпущенное можно 72 часа и только если от пакета никто не зависит, а номер после этого не переиспользуется (политика unpublish npmjs.com, сверено 2026-08-06).',
          'Коммит версий и теги этим прогоном в `main` не уехали — репозиторий и реестр разошлись.',
        ],
        next: [
          `НЕ перезапускай вслепую: прогон посчитает те же номера и упрётся в занятые. Сверься с реестром пакет за пакетом — \`${ASK_REGISTRY}\`.`,
          'Тому, что уехало, номер не поднимают и содержимое не подменяют — уехало то, что уехало.',
          'Недостающее допубликуй, а номера уехавшего внеси в манифесты и теги отдельным PR: реестр — источник истины о том, что уже занято.',
        ],
      };

    case 'published':
      return {
        stage,
        registry: 'complete',
        reversible: false,
        headline: 'Опубликовано ВСЁ, а репозиторий об этом не знает',
        state: [
          '`nx release` прошёл целиком: пакеты лежат в публичном npm.',
          'Упало то, что идёт ПОСЛЕ публикации, — коммит версий и теги остались на раннере и в `main` не уехали.',
          'Реестр ушёл вперёд репозитория: номера заняты, а история про них молчит.',
        ],
        next: [
          'НЕ перезапускай выпуск: с нуля он посчитает те же номера и упрётся в занятые.',
          `Сними состояние из реестра — \`${ASK_REGISTRY}\` по каждому пакету — и донеси его до репозитория отдельным PR: номера в манифесты, теги \`<имя>@<номер>\` на выпущенный коммит.`,
          'Пока теги не стоят, гейт номеров на PR меряет цену изменения не от того выпуска.',
        ],
      };

    case 'delivered':
      return {
        stage,
        registry: 'complete',
        reversible: false,
        headline:
          'Опубликовано ВСЁ и записано в репозиторий — а приёмка выпуск не приняла',
        state: [
          'Пакеты лежат в публичном npm под публичными именами, коммит версий и теги уехали в `main` — реестр и репозиторий сходятся.',
          'Упала ПРИЁМКА: установка выпущенного из публичного реестра в чистый каталог не прошла. Значит выпуск, зелёный в монорепе, у потребителя не работает — тот же класс, что `tasker:BASER2-251`.',
          'Номера при этом заняты навсегда: снять выпущенное можно 72 часа и только если от пакета никто не зависит, а номер после этого не переиспользуется (политика unpublish npmjs.com, сверено 2026-08-06).',
        ],
        next: [
          'Читай сводку приёмки выше: она называет, ЧТО именно не встало — установка, ссылка под внутренним именем, загрузка пакета или первая команда.',
          'НЕ перезапускай выпуск: с нуля он посчитает те же номера и упрётся в занятые.',
          'Уехавшему номер не поднимают и содержимое не подменяют — чини причину и выпускай СЛЕДУЮЩИМ номером.',
          'Пока починка не уехала, пометь сломанный номер в реестре — `npm deprecate <имя>@<номер> "<причина>"`: снять его нельзя, а предупредить потребителя можно.',
        ],
      };

    default:
      return {
        stage: 'unknown',
        registry: 'unknown',
        reversible: false,
        headline:
          'Выпуск отказан, а рубеж не опознан — состояние реестра считай неизвестным',
        state: [
          'Шаг публикации не назвал, чем кончился, поэтому «уехало» и «не уехало» здесь одинаково не доказаны.',
          'Молчаливое «наверное, не уехало» стоит дороже проверки: перезапуск поверх частичной публикации жжёт номера.',
        ],
        next: [
          `Спроси реестр до всякого перезапуска — \`${ASK_REGISTRY}\` по каждому пакету набора.`,
          'Реестр пуст на всех номерах — запускай выпуск заново. Хоть один занят — дальше как при отказе внутри публикации.',
        ],
      };
  }
}

/** Состояние реестра словами — одно место, чтобы формулировки не разъезжались. */
const REGISTRY_WORDING = {
  untouched: 'не уехало ничего',
  'possibly-partial': '**могла уехать часть набора**',
  complete: '**уехал весь набор**',
  unknown: '**неизвестно — проверь**',
};

/**
 * Отказ в markdown для сводки прогона.
 *
 * @param {Refusal} what
 * @returns {string[]} строки
 */
export function render(what) {
  const lines = [
    `## ❌ ${what.headline}`,
    '',
    '| | |',
    '|---|---|',
    `| в публичном реестре | ${REGISTRY_WORDING[what.registry]} |`,
    `| перезапуск с нуля | ${what.reversible ? 'безопасен' : 'ОПАСЕН — сначала прочитай ниже'} |`,
    '',
    '### Что сейчас',
    '',
  ];

  for (const line of what.state) lines.push(`- ${line}`);
  lines.push('', '### Что делать', '');
  for (const line of what.next) lines.push(`- ${line}`);
  lines.push('');

  return lines;
}

/**
 * Запуск в конвейере.
 *
 * @param {string[]} argv аргументы после имени скрипта
 * @returns {number} код выхода
 */
function main(argv) {
  const stage = stageOf(argv[0] ?? '', argv[1] ?? '');
  for (const line of render(refusal(stage))) console.log(line);
  return stage === 'unknown' ? 2 : 0;
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(process.argv[1]).href
) {
  process.exit(main(process.argv.slice(2)));
}
